51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    private final OwnerFieldsValidator ownerFieldsValidator;
69	
70	    private final TelephoneNormalizer telephoneNormalizer;
71	
72	    private final EmailNormalizer emailNormalizer;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper,
78	                                 OwnerFieldsValidator ownerFieldsValidator,
79	                                 TelephoneNormalizer telephoneNormalizer,
80	                                 EmailNormalizer emailNormalizer) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	        this.ownerFieldsValidator = ownerFieldsValidator;
86	        this.telephoneNormalizer = telephoneNormalizer;
87	        this.emailNormalizer = emailNormalizer;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        this.ownerFieldsValidator.validate(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
122	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
123	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
124	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
125	        }
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
136	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
137	        if (currentOwner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        currentOwner.setAddress(ownerFieldsDto.getAddress());
141	        currentOwner.setCity(ownerFieldsDto.getCity());
142	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
143	        currentOwner.setLastName(ownerFieldsDto.getLastName());
144	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
145	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        HttpHeaders headers = new HttpHeaders();
170	        Pet pet = petMapper.toPet(petFieldsDto);
171	        owner.setId(ownerId);
172	        pet.setOwner(owner);
173	        pet.getType().setName(null);
174	        this.clinicService.savePet(pet);
175	        PetDto petDto = petMapper.toPetDto(pet);
176	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
177	            .buildAndExpand(pet.getId()).toUri());
178	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
179	    }
