181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner != null) {
186	            Pet currentPet = this.clinicService.findPetById(petId);
187	            if (currentPet != null) {
188	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
189	                currentPet.setName(petFieldsDto.getName());
190	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
191	                this.clinicService.savePet(currentPet);
192	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	            }
194	        }
195	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
201	        HttpHeaders headers = new HttpHeaders();
202	        Visit visit = visitMapper.toVisit(visitFieldsDto);
203	        Pet pet = new Pet();
204	        pet.setId(petId);
205	        visit.setPet(pet);
206	        this.clinicService.saveVisit(visit);
207	        VisitDto visitDto = visitMapper.toVisitDto(visit);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
209	            .buildAndExpand(visit.getId()).toUri());
210	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
211	    }
212	
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
